action.code:
# Get all playlists
playlist_tracks = set()
page_index = 0
while True:
    result = apis.spotify.get_user_playlists(access_token=token, page_index=page_index)
    if not result.get('items'):
        break
    for playlist in result['items']:
        if playlist.get('id'):
            # Get tracks from this playlist
            playlist_id = playlist['id']
            playlist_page = 0
            while True:
                playlist_result = apis.spotify.get_playlist_tracks(access_token=token, playlist_id=playlist_id, page_index=playlist_page)
                if not playlist_result.get('items'):
                    break
                for item in playlist_result['items']:
                    if item.get('track') and item['track'].get('id'):
                        playlist_tracks.add(item['track']['id'])
                playlist_page += 1
    page_index += 1

print(f"Playlist tracks: {len(playlist_tracks)}")

