# Let me check all transactions from 2023-05-17 to see what's there
all_yesterday = []
for tx in transactions:
    created_date = tx['created_at'][:10]
    if created_date == "2023-05-17":
        all_yesterday.append(tx)

print(f"All transactions from 2023-05-17: {len(all_yesterday)}")
for tx in all_yesterday:
    print(f"  {tx['description']} - {tx['amount']} from {tx['sender']['name']}")

# Let me check all transactions from yesterday (2023-05-17)
all_transactions = apis.venmo.show_transactions(access_token=token, page_index=0)

yesterday_transactions = []
for tx in all_transactions:
    created_date = tx['created_at'][:10]  # Extract date part
    if created_date == "2023-05-17":
        yesterday_transactions.append(tx)

print(f"Found {len(yesterday_transactions)} transactions from yesterday")
for tx in yesterday_transactions:
    print(f"ID: {tx['transaction_id']}, Amount: {tx['amount']}, Description: {tx['description']}, Sender: {tx['sender']['name']}, Receiver: {tx['receiver']['name']}")

# Let me check if there are more pages of transactions
all_txs = []
page = 0
while True:
    txs = apis.venmo.show_transactions(access_token=token, page_index=page)
    if not txs:
        break
    all_txs.extend(txs)
    page += 1

print(f"Total transactions found: {len(all_txs)}")

# Look for Azure Harbor Bistro or transactions from 2023-05-17
print("\nTransactions from 2023-05-17:")
for tx in all_txs:
    created_date = tx['created_at'][:10]
    if created_date == "2023-05-17":
        print(f"Amount: {tx['amount']}, Description: {tx['description']}, Sender: {tx['sender']['name']}, Receiver: {tx['receiver']['name']}")

print("\nTransactions with 'Azure Harbor' in description:")
for tx in all_txs:
    if "Azure Harbor" in tx['description']:
        print(f"Date: {tx['created_at']}, Amount: {tx['amount']}, Description: {tx['description']}, Sender: {tx['sender']['name']}, Receiver: {tx['receiver']['name']}")

# Let me search more broadly for transactions on 2023-05-17 to see all activity
all_may_17_transactions = []
for tx in all_txs:
    created_date = tx['created_at'][:10]
    if created_date == "2023-05-17":
        all_may_17_transactions.append(tx)

print(f"All transactions on 2023-05-17:")
for tx in all_may_17_transactions:
    print(f"Amount: ${tx['amount']}, Description: {tx['description']}, Sender: {tx['sender']['name']}, Receiver: {tx['receiver']['name']}")

