action.code:
# Get file information with creation dates for each file
files_info = []
for file_path in result:
    if not file_path.endswith('/'):  # Only process files, not directories
        file_info = apis.file_system.get_file_info(file_path=file_path, access_token=token)
        files_info.append({
            'path': file_path,
            'info': file_info
        })
        print(f"{file_path}: {file_info}")

# Check if filesystem is available
try:
    fs_result = apis.filesystem.list_files(path="~/downloaded_files/")
    print(fs_result)
except AttributeError:
    print("filesystem module not found")
except Exception as e:
    print(f"Error: {type(e).__name__}: {e}")

# Try alternative names
try:
    fs_result = apis.files.list_files(path="~/downloaded_files/")
    print(fs_result)
except AttributeError:
    print("files module not found")
except Exception as e:
    print(f"Error: {type(e).__name__}: {e}")

