action.code:
try:
    # Try to list files in the directory
    result = apis.file_system.list_files(path='~/my_downloads/')
    print(result)
except AttributeError as e:
    print(f"file_system not available: {e}")
except Exception as e:
    print(f"Error: {e}")

try:
    # Try different possible API names
    result = apis.file_system.list_files(directory='~/my_downloads/')
    print(result)
except AttributeError:
    try:
        result = apis.file_system.get_files(path='~/my_downloads/')
        print(result)
    except AttributeError:
        try:
            result = apis.filesystem.list(path='~/my_downloads/')
            print(result)
        except Exception as e:
            print(f"All attempts failed: {e}")

