action.code:
# Filter for transactions sent in May 2023
may_2023_sent = []
current_date = datetime(2023, 5, 18)
may_start = datetime(2023, 5, 1)

for tx in all_transactions:
    # Check if transaction was sent (direction = 'sent' or similar)
    # Check if date is in May 2023
    if 'date' in tx:
        tx_date = datetime.fromisoformat(tx['date'].replace('Z', '+00:00')).replace(tzinfo=None)
        if tx_date >= may_start and tx_date <= current_date:
            # Check if this is a sent transaction
            if tx.get('direction') == 'sent' or tx.get('type') == 'sent':
                may_2023_sent.append(tx)

print(f"Sent transactions in May 2023: {len(may_2023_sent)}")
for tx in may_2023_sent:
    print(json.dumps(tx, indent=2))

