action.code:
# Now I need to filter for transactions where Paul Miller is the receiver (received) and from 2023
# Let me collect all transactions across all pages
all_received_transactions = []
page_index = 1

while True:
    transactions = apis.venmo.show_transactions(access_token=token, page_index=page_index)

    if not transactions:
        break

    # Filter for transactions where Paul Miller is the receiver
    for trans in transactions:
        if trans['receiver']['email'] == 'paul_mill@gmail.com':
            # Check if transaction is from 2023
            created_year = int(trans['created_at'][:4])
            if created_year == 2023:
                all_received_transactions.append(trans)

    page_index += 1

    # Safety check to avoid infinite loops
    if page_index > 100:
        break

print(f"Total received transactions in 2023: {len(all_received_transactions)}")
for trans in all_received_transactions:
    print(f"  - {trans['description']}: {trans['like_count']} likes")

